import{_ as n,o as a,c as l,a2 as e}from"./chunks/framework.BDmrrkGR.js";const d=JSON.parse('{"title":"160. 相交链表（链表 / 双指针）","description":"","frontmatter":{"title":"160. 相交链表（链表 / 双指针）","date":"2026-09-13T00:00:00.000Z","tags":["CodeTop","LeetCode","链表","双指针","简单"],"category":"codetop","difficulty":"简单","leetcodeId":160,"excerpt":"两个指针分别走完自己的链表后切换到对方链表，最终在交点或 null 相遇。"},"headers":[],"relativePath":"posts/leetcode/codetop/code160-intersection-of-two-linked-lists.md","filePath":"posts/leetcode/codetop/code160-intersection-of-two-linked-lists.md","lastUpdated":1789257371000}'),p={name:"posts/leetcode/codetop/code160-intersection-of-two-linked-lists.md"};function o(t,s,c,r,i,B){return a(),l("div",null,[...s[0]||(s[0]=[e(`<h1 id="_160-相交链表-链表-双指针" tabindex="-1">160. 相交链表（链表 / 双指针） <a class="header-anchor" href="#_160-相交链表-链表-双指针" aria-label="Permalink to &quot;160. 相交链表（链表 / 双指针）&quot;">​</a></h1><h2 id="题目" tabindex="-1">题目 <a class="header-anchor" href="#题目" aria-label="Permalink to &quot;题目&quot;">​</a></h2><p>给你两个单链表的头节点 <code>headA</code> 和 <code>headB</code>，请你找出并返回两个单链表相交的起始节点。如果两个链表不存在相交节点，返回 <code>null</code>。<br> 题目数据保证整个链式结构中不存在环。<br> 注意，函数返回结果后，链表必须保持其原始结构。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p>输入：<code>intersectVal = 8, listA = [4,1,8,4,5], listB = [5,6,1,8,4,5], skipA = 2, skipB = 3</code><br> 输出：返回值为 8 的节点（即两个链表相交于节点 8）</p><p>输入：<code>intersectVal = 0, listA = [2,6,4], listB = [1,5], skipA = 3, skipB = 2</code><br> 输出：<code>null</code>（两个链表不相交）</p><h2 id="解题思路" tabindex="-1">解题思路 <a class="header-anchor" href="#解题思路" aria-label="Permalink to &quot;解题思路&quot;">​</a></h2><p>采用<strong>双指针走对方的路（浪漫相遇法）</strong>。<br> 两个指针 <code>pA</code> 和 <code>pB</code> 分别从 <code>headA</code> 和 <code>headB</code> 出发，各自走到链表末尾后，<strong>切换到对方的链表头继续走</strong>。<br> 这样，两个指针走过的总路程相等（都是 <code>lenA + lenB</code>）。</p><ul><li>如果两个链表相交，它们一定会在交点相遇。</li><li>如果两个链表不相交，它们会同时走到 <code>null</code>，此时返回 <code>null</code>。</li></ul><p>时间复杂度 <code>O(m + n)</code>，空间复杂度 <code>O(1)</code>。</p><h2 id="解答" tabindex="-1">解答 <a class="header-anchor" href="#解答" aria-label="Permalink to &quot;解答&quot;">​</a></h2><div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="color:#7F848E;font-style:italic;">/**</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * Definition for singly-linked list.</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * public class ListNode {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *     int val;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *     ListNode next;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *     ListNode(int x) {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *         val = x;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *         next = null;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> *     }</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> * }</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"> */</span></span>
<span class="line"><span style="color:#C678DD;">public</span><span style="color:#C678DD;"> class</span><span style="color:#E5C07B;"> Solution</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#C678DD;">    public</span><span style="color:#E5C07B;"> ListNode</span><span style="color:#61AFEF;"> getIntersectionNode</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">ListNode</span><span style="color:#E06C75;font-style:italic;"> headA</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">ListNode</span><span style="color:#E06C75;font-style:italic;"> headB</span><span style="color:#ABB2BF;">)</span><span style="color:#ABB2BF;"> {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 边界判断：任一链表为空，则不可能相交</span></span>
<span class="line"><span style="color:#C678DD;">        if</span><span style="color:#ABB2BF;"> (headA </span><span style="color:#56B6C2;">==</span><span style="color:#D19A66;"> null</span><span style="color:#56B6C2;"> ||</span><span style="color:#ABB2BF;"> headB </span><span style="color:#56B6C2;">==</span><span style="color:#D19A66;"> null</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">return</span><span style="color:#D19A66;"> null</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">        ListNode</span><span style="color:#E06C75;"> pA</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> headA; </span><span style="color:#7F848E;font-style:italic;">// pA 从 headA 出发</span></span>
<span class="line"><span style="color:#E5C07B;">        ListNode</span><span style="color:#E06C75;"> pB</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> headB; </span><span style="color:#7F848E;font-style:italic;">// pB 从 headB 出发</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 两个指针一直走，直到相遇（即指向同一个节点）或同时为 null（不相交）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 为什么这样一定能相遇？因为两个指针走的总路程相等（lenA + lenB）</span></span>
<span class="line"><span style="color:#C678DD;">        while</span><span style="color:#ABB2BF;"> (pA </span><span style="color:#56B6C2;">!=</span><span style="color:#ABB2BF;"> pB) {</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">            // pA 走完自己的链表后，切换到 headB 继续走；若已经为 null，则保持 null</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">            // 用三元运算符保证切换只发生一次：走到 null 后就不再切换</span></span>
<span class="line"><span style="color:#ABB2BF;">            pA </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> (pA </span><span style="color:#56B6C2;">==</span><span style="color:#D19A66;"> null</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">?</span><span style="color:#ABB2BF;"> headB </span><span style="color:#C678DD;">:</span><span style="color:#E5C07B;"> pA</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">next</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">            // pB 同理，走完自己的链表后，切换到 headA 继续走</span></span>
<span class="line"><span style="color:#ABB2BF;">            pB </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> (pB </span><span style="color:#56B6C2;">==</span><span style="color:#D19A66;"> null</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">?</span><span style="color:#ABB2BF;"> headA </span><span style="color:#C678DD;">:</span><span style="color:#E5C07B;"> pB</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">next</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">        }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 循环结束时，要么 pA == pB 指向相交节点，要么两者都为 null（不相交）</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">        // 直接返回 pA 即可，因为此时 pA 和 pB 相同</span></span>
<span class="line"><span style="color:#C678DD;">        return</span><span style="color:#ABB2BF;"> pA;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br></div></div>`,12)])])}const b=n(p,[["render",o]]);export{d as __pageData,b as default};
